const view=document.querySelector('#view'),mic=document.querySelector('#mic');
let state='idle',seconds=0,timer,sleepTimer,homeHintDelay,homeHintTimer,flowTimers=[],volume=7,sleepAfterMinutes=5,speakerMuted=false,micMuted=false,callMicMuted=false,cameraOff=false,callMode='voice',deviceModel='voice',remoteViewing=false,wechatContactsEnabled=true,faceTheme='procedural',currentEmoji='neutral',fallbackMood='happy',previous='menu',homeMode='face',gestureStart=null,suppressTap=false;
let roomDigits='',roomError='',roomCode='',roomPassword='',roomHasPassword=false,roomTalking=false;
let roomParticipants=[];
let peer={name:'妈妈',source:'微信',online:true};
let weatherData=null;
let deviceHotspotName='XiaoTai-A1B2',bindingCode='482731';
const contactData=[{name:'妈妈',source:'微信',online:null,color:'#55d68b'},{name:'书房机器人',source:'设备',online:true,color:'#6f9cff'},{name:'张三',source:'微信',online:null,color:'#ffb66f'},{name:'办公室',source:'设备',online:true,color:'#b58aff'}];
const emojis=[['neutral','中性','•'],['happy','开心','⌣'],['laughing','大笑','◡'],['funny','逗趣','◔'],['sad','难过','⌢'],['angry','生气','⌁'],['crying','哭泣','︵'],['loving','喜爱','♥'],['embarrassed','害羞','///'],['surprised','惊讶','○'],['shocked','震惊','◎'],['thinking','思考','…'],['winking','眨眼','◕'],['cool','酷','▰'],['relaxed','放松','﹏'],['delicious','美味','˘'],['kissy','亲亲','ε'],['confident','自信','⌄'],['sleepy','困倦','ᴢ'],['silly','搞怪','↝'],['confused','困惑','?']];
const labels={idle:'安静待机',ambient:'检测到环境音',speech:'检测到人声',listening:'正在聆听',thinking:'AI 正在思考','fallback-emotion':'AI 回复中','call-command':'识别到呼叫指令','call-preparing':'正在启动通话',happy:'AI · 开心',sad:'AI · 难过',surprised:'AI · 惊讶'};
const subs={ambient:'检测到环境声音，正在留意…',speech:'AI：你好呀，我听到你了。',listening:'你：今天心情怎么样？',thinking:'AI：让我想一想…','fallback-emotion':'AI：当然可以，我在听呢。','call-command':'你：呼叫书房机器人','call-preparing':'AI：好的，正在为你呼叫书房机器人。',happy:'AI：见到你我很开心，今天想聊点什么？',sad:'AI：听起来你今天有些难过，我陪着你。',surprised:'AI：哇，原来是这样！'};
const head=(title,back='menu',right='')=>`<div class="screen-head"><button data-go="${back}" aria-label="返回">‹</button><h2>${title}</h2><span>${right}</span></div>`;
const visibleContacts=()=>contactData.filter(c=>c.source!=='微信'||wechatContactsEnabled);
const groupedContacts=()=>['设备','微信'].flatMap(source=>visibleContacts().filter(c=>c.source===source));
const homeContactButton=()=>`<button class="home-wechat-call" onclick="quickFirstContactCall()" aria-label="呼叫第一个联系人"><b>☎</b></button>`;
function homeDots(){return `<div class="home-hint" id="home-hint"><span>◉</span> 轻触屏幕，开始 AI 聊天</div><div class="home-dots"><button data-home="face" class="${homeMode==='face'?'active':''}" aria-label="表情表盘"></button><button data-home="clock" class="${homeMode==='clock'?'active':''}" aria-label="时钟表盘"></button></div>${homeContactButton()}`}
function face(s){if(s==='screen-off')return screenOff();if(s==='network-setup')return apSetup();if(s==='wechat-auth')return wechatAuth();let mood=s==='speech'?'happy':s==='fallback-emotion'?fallbackMood:s==='call-command'?'listening':s==='call-preparing'?'happy':s,status=s==='idle'&&remoteViewing?'● 远程查看中':labels[s];return `<button class="tap-surface" data-talk aria-label="点击开始对话"><div class="chip ${remoteViewing&&s==='idle'?'privacy':''}">${status}</div><div class="face ${mood}"><div class="eye"></div><div class="eye"></div><div class="mouth"></div></div>${['listening','call-command'].includes(s)?'<div class="bars"><i></i><i></i><i></i></div>':''}</button>${subs[s]?`<div class="subtitle">${subs[s]}</div>`:''}${s==='idle'?homeDots():''}<button class="home-menu-button" data-go="menu" aria-label="打开功能菜单">⋯</button>`}
function clockHome(){let d=new Date(),weather=weatherData?.location&&weatherData?.summary?`<span>${weatherData.location} · ${weatherData.summary}</span>`:'',privacy=remoteViewing?'<div class="chip privacy">● 远程查看中</div>':'';return `<button class="clock-home tap-surface" data-talk aria-label="点击开始对话">${privacy}<small id="clock-date">${d.toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'short'})}</small><strong id="clock-time">${d.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})}</strong>${weather}</button>${homeDots()}<button class="home-menu-button" data-go="menu" aria-label="打开功能菜单">⋯</button>`}
function deviceMenu(){return `<div class="device-menu"><button class="menu-back" data-go="idle" aria-label="返回主页">‹</button><h2>功能菜单</h2><div class="device-menu-grid"><button data-go="conversation"><b>◉</b>AI 聊天</button><button data-go="contacts"><b>☎</b>通讯录</button><button data-go="rooms"><b>⌁</b>多人对讲</button><button data-go="emojis"><b>☺</b>表情包</button><button data-go="settings"><b>◖</b>设备设置</button><button data-go="network"><b>◎</b>网络状态</button></div></div>`}
function contacts(){let list=groupedContacts();return `<div class="contacts contacts-page">${head('通讯录','menu',list.length)}<div class="contact-scroll">${list.map((c,index)=>`${index===0||list[index-1].source!==c.source?`<h3 class="contact-group">${c.source==='微信'?'微信联系人':'智能设备'}</h3>`:''}<button class="row" data-contact="${contactData.indexOf(c)}"><b style="background:${c.color}">${c.name[0]}</b><span>${c.name}<small>${c.source==='微信'?'<i class="wechat">微信</i>':'◉ 智能设备 · '+(c.online?'在线':'离线')}</small></span>›</button>`).join('')}</div></div>`}
function contactDetail(){let canCall=peer.source==='微信'||peer.online,video=deviceModel==='video'?`<button data-start-call="video" ${canCall?'':'disabled'}><b>▣</b>视频通话</button>`:'';return `<div class="detail-screen">${head('联系人','contacts')}<div class="detail-avatar" style="background:${peer.color||'#55d68b'}">${peer.name[0]}</div><h2>${peer.name}</h2><p>${peer.source==='微信'?'<i class="wechat">微信</i>':'◉ 设备互联 · '+(peer.online?'在线':'离线')}</p><div class="call-choice ${deviceModel==='voice'?'voice-only':''}"><button data-start-call="voice" ${canCall?'':'disabled'}><b>☎</b>语音通话</button>${video}</div>${canCall?'':'<small>当前离线，暂时无法呼叫</small>'}</div>`}
function call(s){if(s==='dialing'){let requested=document.activeElement?.dataset?.startCall;if(requested){callMode=requested;callMicMuted=false;cameraOff=false}}let msg=s==='incoming'?(callMode==='video'?'视频来电':'语音来电'):s==='dialing'?'正在呼叫…':s==='connecting'?'正在接通…':s==='connected'?'00:00':s==='rejected'?'对方已拒绝':s==='timeout'?'无人接听':'通话已结束';let live=['dialing','connecting','connected'].includes(s);let controls=s==='incoming'?'<div class="actions labeled"><button data-call="rejected"><b>×</b><span>拒绝</span></button><button class="accept" data-call="connecting"><b>☎</b><span>接听</span></button></div>':live?`<div class="call-toolbar"><button data-call-mic class="${callMicMuted?'off':''}"><b>${callMicMuted?'×':'●'}</b><span>${callMicMuted?'取消静音':'静音'}</span></button>${callMode==='video'?`<button data-camera class="${cameraOff?'off':''}"><b>${cameraOff?'×':'▣'}</b><span>${cameraOff?'开启摄像头':'关闭摄像头'}</span></button>`:''}<button class="end-call" data-call="ended"><b>☎</b><span>挂断</span></button></div>`:'<button class="return-home" data-go="idle">返回主页</button>';let channel=peer.source==='微信'?'<i class="wechat">微信</i>':'◉ 设备互联';let video=callMode==='video'&&live?`<div class="video-stage ${cameraOff?'camera-off':''}"><div class="remote-person">${peer.name[0]}</div><div class="self-view">${cameraOff?'摄像头已关闭':'我的画面'}</div></div>`:'';return `<div class="call ${callMode}"><div class="source">${channel} · ${callMode==='video'?'视频通话':'语音通话'}</div>${video||`<div class="avatar" style="background:${peer.color||'#55d68b'}">${peer.name[0]}</div>`}<h2>${peer.name}</h2><p id="callmsg">${msg}${callMicMuted?' · 已静音':''}</p></div>${controls}`}
function emojiLibrary(){return `<div class="emoji-screen">${head('表情包','menu','21')}<div class="emoji-grid">${emojis.map(e=>`<button class="emoji-item ${currentEmoji===e[0]?'active':''}" data-emoji="${e[0]}"><b>${e[2]}</b><span>${e[1]}</span></button>`).join('')}</div></div>`}
function emojiPreview(){let row=emojis.find(e=>e[0]===currentEmoji)||emojis[0],mood={laughing:'happy',funny:'silly',shocked:'surprised',relaxed:'sleepy',delicious:'happy',kissy:'happy',confident:'cool'}[currentEmoji]||currentEmoji;return `<div class="emoji-preview-screen">${head(row[1],'emojis')}<div class="face ${mood} emoji-preview"><div class="eye"></div><div class="eye"></div><div class="mouth"></div></div><button class="apply-emoji" data-apply-emoji>应用到主页</button></div>`}
function conversation(){return `<div class="conversation-screen">${head('AI 聊天','menu','●')}<div class="conversation-status">正在聆听 · 可随时说话</div><div class="dialog"><div class="bubble user">帮我打微信给妈妈</div><div class="bubble">好的，正在为你准备微信语音呼叫。</div><div class="bubble user">先等等，陪我聊一会儿吧。</div><div class="bubble">当然可以，我在听呢。</div></div><div class="subtitle">AI：当然可以，我在听呢。</div></div>`}
function resetRoomInput(){roomDigits='';roomError=''}
function numberPad(max){return `<div class="number-pad">${[1,2,3,4,5,6,7,8,9].map(n=>`<button data-room-digit="${n}" ${roomDigits.length>=max?'disabled':''}>${n}</button>`).join('')}<button class="blank" tabindex="-1"></button><button data-room-digit="0" ${roomDigits.length>=max?'disabled':''}>0</button><button data-room-delete aria-label="删除一位">⌫</button></div>`}
function digitSlots(length){return `<div class="digit-slots ${length===4?'short':''}">${Array.from({length},(_,i)=>`<i class="${roomDigits[i]?'filled':''}">${roomDigits[i]||''}</i>`).join('')}</div>`}
function rooms(){return `<div class="room-screen">${head('多人对讲','menu')}<div class="room-hero"><div class="room-radio">⌁</div><h3>和大家一起说话</h3><p>最多 100 人同时在线</p></div><div class="room-entry"><button data-room-start="create"><b>＋</b><span>创建房间<small>获得 6 位房间码</small></span></button><button data-room-start="join"><b>→</b><span>加入房间<small>输入房间码</small></span></button></div><div class="room-tip"><i>●</i> 无密码房间可直接加入</div></div>`}
function roomCreate(){return `<div class="room-screen">${head('创建房间','rooms')}<div class="create-room-card"><div class="room-radio small">＋</div><h3>设置加入方式</h3><p>房间创建后最多容纳 100 人</p></div><div class="room-create-options"><button data-create-open><b>开放房间</b><small>输入房间码即可加入</small><span>›</span></button><button data-create-password><b>密码房间</b><small>需要 4 位数字密码</small><span>›</span></button></div></div>`}
function roomCodeInput(){let ready=roomDigits.length===6;return `<div class="room-screen keypad-screen">${head('加入房间','rooms')}<p class="input-label">请输入 6 位房间码</p>${digitSlots(6)}${roomError?`<p class="room-error">${roomError}</p>`:'<p class="input-help">房间码由创建者提供</p>'}${numberPad(6)}<button class="room-next" data-room-code-next ${ready?'':'disabled'}>下一步</button></div>`}
function roomPasswordInput(mode='join'){let ready=roomDigits.length===4,title=mode==='create'?'设置密码':'输入密码';return `<div class="room-screen keypad-screen">${head(title,mode==='create'?'room-create':'rooms')}<p class="input-label">${mode==='create'?'设置 4 位数字密码':'房间 '+roomCode+' 需要密码'}</p>${digitSlots(4)}${roomError?`<p class="room-error">${roomError}</p>`:`<p class="input-help">${mode==='create'?'创建后可以告诉其他用户':'密码由创建者提供'}</p>`}${numberPad(4)}<button class="room-next" data-room-password-next="${mode}" ${ready?'':'disabled'}>${mode==='create'?'创建房间':'加入房间'}</button></div>`}
function defaultParticipants(createdHere){return createdHere?[{name:'我',role:'已加入',color:'#65d9f8',self:true},{name:'妈妈',role:'正在说话',color:'#55d68b',speaking:true},{name:'书房机器人',role:'在线',color:'#6f9cff'},{name:'张三',role:'正在说话',color:'#ffb66f',speaking:true}]:[{name:'周末骑行队长',role:'在线',color:'#65d9f8'},{name:'妈妈',role:'正在说话',color:'#55d68b',speaking:true},{name:'我',role:'已加入',color:'#6f9cff',self:true},{name:'张三',role:'在线',color:'#ffb66f'}]}
function createRoom(password=''){roomCode='286419';roomPassword=password;roomHasPassword=Boolean(password);roomParticipants=defaultParticipants(true);render('room-created')}
function enterRoom(){roomParticipants=defaultParticipants(false);render('room-live')}
function roomCreated(){return `<div class="room-screen">${head('房间已创建','rooms')}<div class="room-success">✓</div><p class="success-label">把加入信息告诉其他用户</p><div class="room-share"><small>房间码</small><strong>${roomCode.slice(0,3)} ${roomCode.slice(3)}</strong><div><span>密码</span><b>${roomHasPassword?roomPassword:'无密码'}</b></div></div><p class="share-help">${roomHasPassword?'对方需要输入房间码和密码':'其他用户输入房间码即可加入'}</p><button class="room-primary" data-enter-created>进入房间</button></div>`}
function roomLive(){let speakers=roomParticipants.filter(p=>p.speaking).length+(roomTalking?1:0);return `<div class="room-screen live-room">${head('多人对讲','rooms',`${roomParticipants.length}/100`)}<div class="live-summary"><div><span class="live-dot"></span><b>${speakers?`${speakers} 人正在说话`:'房间很安静'}</b></div><small>房间码 ${roomCode||'826419'}${roomHasPassword?' · 有密码':' · 无密码'}</small></div><div class="participant-list">${roomParticipants.map(p=>`<div class="participant ${p.speaking?'speaking':''}"><b style="background:${p.color}">${p.name[0]}</b><span>${p.name}<small>${p.role}</small></span>${p.speaking?'<i class="sound-wave">▮ ▮ ▮</i>':''}</div>`).join('')}</div><div class="ptt-wrap"><button class="ptt ${roomTalking?'talking':''}" data-ptt><b>${roomTalking?'●':'◉'}</b><span>${roomTalking?'松开发送':'按住说话'}</span></button><button class="leave-room" data-leave-room>退出</button></div></div>`}
function settings(){return `<div class="settings-screen">${head('设备设置','menu')}<div class="device-setting"><div><span>扬声器音量</span><strong>${speakerMuted?'静音':volume*10+'%'}</strong></div><div class="stepper"><button data-vol="-1">−</button><b>${speakerMuted?'×':volume}</b><button data-vol="1">＋</button></div><button class="inline-toggle ${speakerMuted?'on':''}" data-device-speaker>${speakerMuted?'取消扬声器静音':'扬声器静音'}</button></div><div class="device-setting"><div><span>无声后自动息屏</span><strong>${sleepAfterMinutes===0?'从不':sleepAfterMinutes+' 分钟'}</strong></div><div class="sleep-options">${[1,5,10,30,0].map(v=>`<button data-sleep="${v}" class="${sleepAfterMinutes===v?'active':''}">${v===0?'从不':v+'分'}</button>`).join('')}</div></div><button class="device-setting setting-button" data-device-mic><span>麦克风</span><strong>${micMuted?'已静音':'开启'}</strong></button><div class="device-setting"><div><span>Wi‑Fi</span><strong>已连接</strong></div></div></div>`}
function screenOff(){return `<button class="screen-off" data-wake aria-label="轻触点亮屏幕"></button>`}
function apSetup(){return `<div class="ap-setup"><div class="ap-icon">⌁</div><h2>需要连接网络</h2><p>请使用手机完成 AP 配网</p><ol><li><b>1</b><span>打开手机 Wi-Fi，连接设备热点<br><strong>${deviceHotspotName}</strong></span></li><li><b>2</b><span>浏览器打开<br><strong>http://192.168.6.1</strong></span></li><li><b>3</b><span>选择家中 Wi-Fi<br>并输入密码</span></li></ol><button data-go="idle">我已完成配网</button><small>连接成功后设备会自动进入首页</small></div>`}
function wechatAuth(){return `<div class="wechat-auth-screen">${head('微信授权','idle')}<div class="wechat-auth-icon">微</div><h2>还没有微信联系人</h2><p>请使用微信扫描小程序码<br>授权并添加联系人</p><div class="miniapp-code" aria-label="微信小程序码示意"><div class="qr-pattern"></div><b>小程序码</b></div><div class="wechat-auth-status"><i></i>等待微信授权…</div><button class="other-contact-button" data-go="contacts">选择联系人</button><small>授权成功后，联系人会自动同步到设备</small></div>`}
function binding(){return `<div class="binding-screen"><div class="binding-icon">⌁</div><div class="binding-label">绑定设备</div><h2>${bindingCode.slice(0,3)} ${bindingCode.slice(3)}</h2><p>请在手机端输入屏幕上的 6 位验证码<br>设备将播报验证码 3 次</p><button data-binding-retry>重新获取验证码</button><button class="binding-done" data-go="idle">我已完成绑定</button><small>验证码仅在本次绑定窗口内有效</small></div>`}
function network(){return `<div class="network-screen"><button class="network-back" data-go="menu">‹</button><div class="network-icon">⌁</div><h2>网络状态良好</h2><p>Wi-Fi：已连接<br>TiRTC / MQTT：在线</p><button data-retry>重新检测</button><button data-go="network-setup">重新配网</button></div>`}
function volumeToast(){return `<div class="volume-toast">扬声器音量<b>${speakerMuted?'静音':volume*10+'%'}</b></div>`}
function syncExternal(){document.querySelector('#volume-value').textContent=speakerMuted?'静音':volume*10+'%';document.querySelector('#volume-number').textContent=speakerMuted?'×':volume;document.querySelector('#speaker-mute').classList.toggle('on',speakerMuted);document.querySelector('#speaker-mute').textContent=speakerMuted?'取消扬声器静音':'扬声器静音';mic.classList.toggle('muted',micMuted);mic.textContent=micMuted?'× 麦克风':'● 麦克风'}
function adjustVolume(delta,toast=false){speakerMuted=false;volume=Math.max(0,Math.min(10,volume+delta));syncExternal();render('settings');if(toast)view.insertAdjacentHTML('beforeend',volumeToast())}
function render(s){clearInterval(timer);if(!['listening','thinking','happy','surprised','sad'].includes(s))clearFlow();previous=state;state=s;document.querySelectorAll('[data-state]').forEach(b=>b.classList.toggle('active',b.dataset.state===s));if(s==='idle'&&homeMode==='clock')view.innerHTML=clockHome();else if(s==='menu')view.innerHTML=deviceMenu();else if(s==='contacts')view.innerHTML=contacts();else if(s==='contact')view.innerHTML=contactDetail();else if(s==='emojis')view.innerHTML=emojiLibrary();else if(s==='emoji-preview')view.innerHTML=emojiPreview();else if(s==='conversation')view.innerHTML=conversation();else if(s==='rooms')view.innerHTML=rooms();else if(s==='room-create')view.innerHTML=roomCreate();else if(s==='room-code')view.innerHTML=roomCodeInput();else if(s==='room-password')view.innerHTML=roomPasswordInput('join');else if(s==='room-create-password')view.innerHTML=roomPasswordInput('create');else if(s==='room-created')view.innerHTML=roomCreated();else if(s==='room-live')view.innerHTML=roomLive();else if(s==='settings')view.innerHTML=settings();else if(s==='network')view.innerHTML=network();else if(s==='binding')view.innerHTML=binding();else if(['incoming','dialing','connecting','connected','rejected','ended','timeout'].includes(s))view.innerHTML=call(s);else view.innerHTML=faceTheme==='otto'&&s==='idle'?(()=>{let html=emojiPreview().replace('<button class="apply-emoji" data-apply-emoji>应用到主页</button>',homeDots()+'<button class="home-menu-button" data-go="menu">⋯</button>');return html})():face(s);bind();if(s==='idle'&&homeMode==='clock')timer=setInterval(updateClock,1000);if(s==='connecting')setTimeout(()=>{if(state==='connecting')render('connected')},1300);if(s==='connected'){seconds=0;timer=setInterval(()=>{seconds++;let el=document.querySelector('#callmsg');if(el)el.textContent=String(seconds/60|0).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')},1000)}}
function clearHomeHint(){clearTimeout(homeHintDelay);clearInterval(homeHintTimer)}
function showHomeHint(){let hint=document.querySelector('#home-hint');if(!hint||state!=='idle')return;hint.classList.add('show');setTimeout(()=>hint.classList.remove('show'),3200)}
function scheduleHomeHint(){clearHomeHint();homeHintDelay=setTimeout(showHomeHint,600);homeHintTimer=setInterval(showHomeHint,12000)}
function manageSleepTimer(){clearTimeout(sleepTimer);if(state==='idle'&&!remoteViewing&&sleepAfterMinutes>0)sleepTimer=setTimeout(()=>render('screen-off'),sleepAfterMinutes*60*1000);if(['ambient','speech'].includes(state))flowTimers.push(setTimeout(()=>{if(['ambient','speech'].includes(state))render('idle')},4500));document.querySelectorAll('[data-call-mic]').forEach(b=>b.onclick=()=>{callMicMuted=!callMicMuted;render(state)});document.querySelectorAll('[data-camera]').forEach(b=>b.onclick=()=>{cameraOff=!cameraOff;render(state)})}
function clearFlow(){clearHomeHint();flowTimers.forEach(clearTimeout);flowTimers=[]}
function startConversation(){if(micMuted){view.insertAdjacentHTML('beforeend','<div class="subtitle">麦克风已静音，请先开启麦克风</div>');return}clearFlow();render('listening');flowTimers.push(setTimeout(()=>render('thinking'),1800));flowTimers.push(setTimeout(()=>{fallbackMood=['happy','surprised','winking','silly','cool'][Math.floor(Math.random()*5)];render('fallback-emotion');flowTimers.push(setTimeout(()=>{if(state==='fallback-emotion')render('idle')},3600))},3300))}
function startAiCall(){clearFlow();peer=contactData[1];callMode='voice';callMicMuted=false;cameraOff=false;render('call-command');flowTimers.push(setTimeout(()=>{render('call-preparing');flowTimers.push(setTimeout(()=>render('dialing'),1400))},1200))}
function quickFirstContactCall(){let first=visibleContacts()[0];if(!first){render('wechat-auth');return}peer=first;callMode='voice';callMicMuted=false;cameraOff=false;render('dialing')}
function toggleWechatContacts(button){wechatContactsEnabled=!wechatContactsEnabled;button.classList.toggle('active',!wechatContactsEnabled);button.textContent=wechatContactsEnabled?'模拟无微信联系人':'恢复微信联系人';render('idle')}
function updateClock(){let d=new Date(),t=document.querySelector('#clock-time'),q=document.querySelector('#clock-date');if(t)t.textContent=d.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});if(q)q.textContent=d.toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'short'})}
function switchHome(mode){homeMode=mode;render('idle')}
function bind(){manageSleepTimer();if(state==='idle')scheduleHomeHint();else clearHomeHint();document.querySelectorAll('[data-go]').forEach(b=>b.onclick=e=>{e.stopPropagation();render(b.dataset.go)});document.querySelectorAll('[data-home]').forEach(b=>b.onclick=e=>{e.stopPropagation();switchHome(b.dataset.home)});document.querySelectorAll('[data-talk]').forEach(b=>b.onclick=()=>{if(!suppressTap)startConversation()});document.querySelectorAll('[data-wake]').forEach(b=>b.onclick=()=>render('idle'));document.querySelectorAll('[data-sleep]').forEach(b=>b.onclick=()=>{sleepAfterMinutes=Number(b.dataset.sleep);render('settings')});document.querySelectorAll('[data-call]').forEach(b=>b.onclick=()=>render(b.dataset.call));document.querySelectorAll('[data-contact]').forEach(b=>b.onclick=()=>{peer=contactData[Number(b.dataset.contact)];render('contact')});document.querySelectorAll('[data-start-call]').forEach(b=>b.onclick=()=>render('dialing'));document.querySelectorAll('[data-emoji]').forEach(b=>b.onclick=()=>{currentEmoji=b.dataset.emoji;render('emoji-preview')});document.querySelectorAll('[data-apply-emoji]').forEach(b=>b.onclick=()=>{faceTheme='otto';homeMode='face';syncTheme();render('idle')});document.querySelectorAll('[data-vol]').forEach(b=>b.onclick=()=>adjustVolume(Number(b.dataset.vol)));document.querySelectorAll('[data-device-speaker]').forEach(b=>b.onclick=()=>{speakerMuted=!speakerMuted;syncExternal();render('settings')});document.querySelectorAll('[data-device-mic],[data-conv-mic]').forEach(b=>b.onclick=()=>{micMuted=!micMuted;syncExternal();render(state)});let retry=document.querySelector('[data-retry]');if(retry)retry.onclick=()=>{retry.textContent='检测中…';setTimeout(()=>{retry.textContent='连接正常 ✓'},900)};let bindingRetry=document.querySelector('[data-binding-retry]');if(bindingRetry)bindingRetry.onclick=()=>{bindingCode=String(Math.floor(100000+Math.random()*900000));render('binding')};bindSwipe()}
view.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.roomStart){resetRoomInput();render(b.dataset.roomStart==='create'?'room-create':'room-code')}else if(b.dataset.roomDigit){let max=state==='room-code'?6:4;if(roomDigits.length<max){roomDigits+=b.dataset.roomDigit;roomError='';render(state)}}else if(b.hasAttribute('data-room-delete')){roomDigits=roomDigits.slice(0,-1);roomError='';render(state)}else if(b.hasAttribute('data-room-code-next')){roomCode=roomDigits;roomHasPassword=roomCode!=='208816';if(roomHasPassword){resetRoomInput();render('room-password')}else enterRoom()}else if(b.hasAttribute('data-create-open'))createRoom('');else if(b.hasAttribute('data-create-password')){resetRoomInput();render('room-create-password')}else if(b.dataset.roomPasswordNext){if(b.dataset.roomPasswordNext==='create')createRoom(roomDigits);else if(roomDigits==='5732'){roomPassword=roomDigits;enterRoom()}else{roomError='密码不正确，请重试';roomDigits='';render('room-password')}}else if(b.hasAttribute('data-enter-created'))render('room-live');else if(b.hasAttribute('data-leave-room')){roomTalking=false;render('rooms')}});
view.addEventListener('pointerdown',e=>{let ptt=e.target.closest('[data-ptt]');if(!ptt)return;if(micMuted){view.insertAdjacentHTML('beforeend','<div class="subtitle">麦克风已静音，请先开启麦克风</div>');return}roomTalking=true;ptt.setPointerCapture?.(e.pointerId);ptt.classList.add('talking');ptt.querySelector('span').textContent='松开发送'});
view.addEventListener('pointerup',e=>{let ptt=e.target.closest('[data-ptt]')||document.querySelector('[data-ptt].talking');if(!ptt)return;roomTalking=false;ptt.classList.remove('talking');ptt.querySelector('span').textContent='按住说话'});
function bindSwipe(){let screen=document.querySelector('.screen');screen.onpointerdown=e=>{gestureStart={x:e.clientX,y:e.clientY}};screen.onpointerup=e=>{if(state!=='idle'||!gestureStart)return;let dx=e.clientX-gestureStart.x;if(Math.abs(dx)>45){suppressTap=true;switchHome(dx<0?'clock':'face');setTimeout(()=>suppressTap=false,120)}gestureStart=null}}
function syncTheme(){document.querySelectorAll('[data-theme]').forEach(b=>b.classList.toggle('active',b.dataset.theme===faceTheme))}
document.querySelectorAll('[data-state]').forEach(b=>b.onclick=()=>{if(b.dataset.state==='incoming')peer=contactData[0];if(b.dataset.state==='dialing')peer=contactData[1];render(b.dataset.state)});
document.querySelectorAll('[data-home-mode]').forEach(b=>b.onclick=()=>switchHome(b.dataset.homeMode));
document.querySelectorAll('[data-device-model]').forEach(b=>b.onclick=()=>{deviceModel=b.dataset.deviceModel;if(deviceModel==='voice'){callMode='voice';remoteViewing=false;let remoteButton=document.querySelector('[data-remote-view]');if(remoteButton){remoteButton.classList.remove('active');remoteButton.textContent='模拟音视频实时查看'}}document.querySelectorAll('[data-device-model]').forEach(x=>x.classList.toggle('active',x.dataset.deviceModel===deviceModel));render(state==='contact'?'contact':'idle')});
document.querySelectorAll('[data-ai-call]').forEach(b=>b.onclick=()=>startAiCall());
document.querySelectorAll('[data-room-demo]').forEach(b=>b.onclick=()=>{let mode=b.dataset.roomDemo;if(mode==='created'){createRoom('5732');render('room-live');return}roomCode=mode==='open'?'208816':'826419';roomHasPassword=mode==='secret';roomPassword=mode==='secret'?'5732':'';enterRoom()});
function h5DeviceList(){let page=document.querySelector('#h5-web-view');if(!page)return;page.innerHTML='<div class="h5-room-card h5-device-card"><div class="h5-device-heading"><div class="h5-device-avatar"><i></i></div><div class="h5-device-identity"><b>客厅小钛</b><span><i></i> 在线 · 当前空闲</span></div><button class="h5-more" data-h5-device-menu aria-label="设备操作">•••</button></div><div class="h5-device-id">设备 ID：TIRZ00000001</div><div class="h5-config-list"><div class="h5-device-context"><span><b>AI 角色</b><small>当前：小钛伙伴</small></span><em>›</em></div><div class="h5-device-context"><span><b>多人对讲</b><small>当前未加入房间</small></span><em>›</em></div></div><div class="h5-feature-grid"><button><b>▣</b><span>实时</span></button><button><b>☎</b><span>联系人</span></button><button><b>AI</b><span>AI 角色</span></button><button class="active" data-h5-room-open><b>⌁</b><span>多人对讲</span></button></div></div>';bindH5RoomPanel()}
function h5DeviceActions(){let page=document.querySelector('#h5-web-view');if(!page)return;page.insertAdjacentHTML('beforeend','<button class="h5-sheet-mask" data-h5-overlay-close aria-label="关闭"></button><div class="h5-action-sheet"><button data-h5-rename>修改设备名称</button><button data-h5-device-info>设备信息</button><button class="danger">解绑设备</button><button data-h5-overlay-close>取消</button></div>');bindH5RoomPanel()}
function h5DeviceInfo(){h5DeviceList();let page=document.querySelector('#h5-web-view');page.insertAdjacentHTML('beforeend','<button class="h5-sheet-mask" data-h5-overlay-close aria-label="关闭"></button><div class="h5-info-modal"><h3>客厅小钛</h3><p>设备 ID：TIRZ00000001<br>MAC：9C:13:9E:8B:AF:1C</p><h4>逻辑媒体流</h4><div class="h5-capability"><b>实时查看</b><span>上行：音频 10、视频 11</span><span>下行：音频 14、视频 15</span><small>编码和画面方向由设备能力上报</small></div><div class="h5-capability"><b>设备通话</b><span>双向：音频 10、视频 11</span><small>无摄像头设备只启用音频</small></div><div class="h5-capability"><b>微信 VoIP</b><span>双向：音频 0、视频 1</span><small>编码和分辨率以开发板说明为准</small></div><div class="h5-modal-actions"><button data-h5-overlay-close>关闭</button><button data-h5-copy-info>复制信息</button></div></div>');bindH5RoomPanel()}
function h5DeviceRename(){h5DeviceList();let page=document.querySelector('#h5-web-view');page.insertAdjacentHTML('beforeend','<button class="h5-sheet-mask" data-h5-overlay-close aria-label="关闭"></button><div class="h5-rename-modal"><h3>设置设备名称</h3><p>该名称用于设备列表和来电显示，最多 13 个字符。</p><input maxlength="13" value="客厅小钛"><div class="h5-modal-actions"><button data-h5-overlay-close>取消</button><button data-h5-overlay-close>保存名称</button></div></div>');bindH5RoomPanel()}
function h5RoomShell(content){let page=document.querySelector('#h5-web-view');if(!page)return;page.innerHTML=`<div class="h5-room-card h5-room-page"><div class="h5-page-head"><button data-h5-device-back>‹</button><span><small>客厅小钛</small><b>多人对讲</b></span><em>在线</em></div>${content}</div>`;bindH5RoomPanel()}
function h5RoomHome(message='当前未加入多人对讲'){h5RoomShell(`<p>${message}</p><div class="h5-room-actions"><button data-h5-room-create>新建房间</button><button data-h5-room-join>加入房间</button></div><small>房间有人在线时一直存在；连续空房 24 小时后自动解散</small>`)}
function h5RoomCreate(){h5RoomShell('<p><b>新建房间</b><br>创建成功后，客厅小钛将自动进入</p><div class="h5-room-actions"><button data-h5-create-mode="open">无密码房间</button><button data-h5-create-mode="secret">设置 4 位密码</button></div><button class="h5-link" data-h5-room-home>返回上一步</button>')}
function h5RoomJoin(){h5RoomShell('<p><b>加入房间</b><br>输入他人提供的房间信息</p><label class="h5-field">6 位房间号<input id="h5-room-code" inputmode="numeric" maxlength="6" value="028615"></label><label class="h5-field">4 位密码（可为空）<input id="h5-room-password" inputmode="numeric" maxlength="4" value="0573"></label><button class="h5-primary" data-h5-join-confirm>加入房间</button><button class="h5-link" data-h5-room-home>返回上一步</button>')}
function h5RoomActive(code,secret){h5RoomShell(`<div class="h5-live"><span><i></i> 客厅小钛已加入</span><b>${code.slice(0,3)} ${code.slice(3)}</b><small>${secret?'有密码':'无密码'} · 3 人在线</small></div><p>按住设备上的说话键即可发言</p><button class="h5-danger" data-h5-room-leave>退出房间</button><small>退出当前设备不会立即解散房间；连续空房 24 小时后自动解散</small>`)}
function bindH5RoomPanel(){document.querySelectorAll('[data-h5-room-open]').forEach(b=>b.onclick=()=>h5RoomHome());document.querySelectorAll('[data-h5-device-menu]').forEach(b=>b.onclick=h5DeviceActions);document.querySelectorAll('[data-h5-device-info]').forEach(b=>b.onclick=h5DeviceInfo);document.querySelectorAll('[data-h5-rename]').forEach(b=>b.onclick=h5DeviceRename);document.querySelectorAll('[data-h5-overlay-close]').forEach(b=>b.onclick=h5DeviceList);document.querySelectorAll('[data-h5-copy-info]').forEach(b=>b.onclick=()=>{b.textContent='已复制'});document.querySelectorAll('[data-h5-device-back]').forEach(b=>b.onclick=h5DeviceList);document.querySelectorAll('[data-h5-room-home]').forEach(b=>b.onclick=()=>h5RoomHome());document.querySelectorAll('[data-h5-room-create]').forEach(b=>b.onclick=h5RoomCreate);document.querySelectorAll('[data-h5-room-join]').forEach(b=>b.onclick=h5RoomJoin);document.querySelectorAll('[data-h5-create-mode]').forEach(b=>b.onclick=()=>{let secret=b.dataset.h5CreateMode==='secret';h5RoomShell(`<p>正在创建${secret?'密码':'无密码'}房间并通知客厅小钛…</p>`);setTimeout(()=>h5RoomActive('208816',secret),650)});document.querySelectorAll('[data-h5-join-confirm]').forEach(b=>b.onclick=()=>{let code=(document.querySelector('#h5-room-code')?.value||'').replace(/\D/g,'').slice(0,6),password=(document.querySelector('#h5-room-password')?.value||'').replace(/\D/g,'').slice(0,4);if(code.length!==6){let p=document.querySelector('.h5-room-page>p');if(p)p.innerHTML='<b>请输入完整的 6 位房间号</b>';return}b.disabled=true;b.textContent='正在加入…';setTimeout(()=>h5RoomActive(code,password.length>0),650)});document.querySelectorAll('[data-h5-room-leave]').forEach(b=>b.onclick=()=>{b.disabled=true;b.textContent='正在退出…';setTimeout(()=>h5RoomHome('客厅小钛已退出房间'),500)})}
h5DeviceList();
document.querySelectorAll('[data-remote-view]').forEach(b=>b.onclick=()=>{if(deviceModel!=='video'){deviceModel='video';document.querySelectorAll('[data-device-model]').forEach(x=>x.classList.toggle('active',x.dataset.deviceModel==='video'))}remoteViewing=!remoteViewing;b.classList.toggle('active',remoteViewing);b.textContent=remoteViewing?'结束实时查看':'模拟音视频实时查看';render('idle')});
document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{faceTheme=b.dataset.theme;syncTheme();render(faceTheme==='otto'?'emojis':'idle')});
document.querySelector('#mute').onclick=()=>{micMuted=!micMuted;syncExternal()};
document.querySelector('#volume-down').onclick=()=>{speakerMuted=false;volume=Math.max(0,volume-1);syncExternal()};document.querySelector('#volume-up').onclick=()=>{speakerMuted=false;volume=Math.min(10,volume+1);syncExternal()};document.querySelector('#speaker-mute').onclick=()=>{speakerMuted=!speakerMuted;syncExternal()};
syncExternal();syncTheme();render('idle');
